raw=(B/'sources'/SOURCE).read_bytes();lines=raw.decode('utf-8-sig').splitlines(keepends=True);assert len(lines)==1080
rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source']!=SOURCE:continue
  a=u['location']['startLine'];z=u['location']['endLine'];assert ''.join(lines[a-1:z])==u['text']
  _,subject,basis,judgment,limits=max((s for s in specs if s[0]<=a),key=lambda s:s[0])
  path=P/f'campaign3-history-{basis}-rev1/review.json'
  rows.append(dict(occurrenceId=u['id'],location=u['location'],text=u['text'],subject=subject,judgment=judgment,limits=limits,
   priorReview=dict(path=path.as_posix(),sha256=sha(path)),obligations=['RO-C3-019','RO-C3-020','RO-C3-021']))
covered={n for r in rows for n in range(r['location']['startLine'],r['location']['endLine']+1)}
